1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	    <meta charset="UTF-8">
5	    <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover">
6	    <title>Project Entry</title>
7	    <style>
8	        /* Design Plan: Clean, data-focused UI for table schema design
9	           Layout: Left sidebar (tables list) | Main (column editor) | Right (field type picker)
10	           Type: Inter for UI, monospace for config
11	           Color: Neutral grays with blue accent */
12	
13	        :root {
14	            --bg: #ffffff;
15	            --surface: #f8f9fa;
16	            --border: #e0e1e6;
17	            --text-primary: #1a1d29;
18	            --text-secondary: #6b7280;
19	            --accent: #2563eb;
20	            --accent-light: #dbeafe;
21	            --error: #dc2626;
22	            --success: #16a34a;
23	            --warning: #ea580c;
24	
25	            --font-system: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", sans-serif;
26	            --font-mono: "SF Mono", Monaco, "Cascadia Code", "Roboto Mono", Consolas, monospace;
27	
28	            color-scheme: light;
29	        }
30	
31	        @media (prefers-color-scheme: dark) {
32	            :root:not([data-theme="light"]) {
33	                --bg: #0f1419;
34	                --surface: #1a1f2e;
35	                --border: #2d3748;
36	                --text-primary: #f0f4f8;
37	                --text-secondary: #a0aec0;
38	                --accent: #3b82f6;
39	                --accent-light: #1e3a8a;
40	                --error: #ef4444;
41	                --success: #22c55e;
42	                --warning: #f97316;
43	                color-scheme: dark;
44	            }
45	        }
46	
47	        :root[data-theme="dark"] {
48	            --bg: #0f1419;
49	            --surface: #1a1f2e;
50	            --border: #2d3748;
51	            --text-primary: #f0f4f8;
52	            --text-secondary: #a0aec0;
53	            --accent: #3b82f6;
54	            --accent-light: #1e3a8a;
55	            --error: #ef4444;
56	            --success: #22c55e;
57	            --warning: #f97316;
58	            color-scheme: dark;
59	        }
60	
61	        * {
62	            box-sizing: border-box;
63	        }
64	
65	        html, body {
66	            height: 100%;
67	            margin: 0;
68	            padding: 0;
69	            font-family: var(--font-system);
70	            font-size: 14px;
71	            line-height: 1.5;
72	            color: var(--text-primary);
73	            background: var(--bg);
74	        }
75	
76	        body {
77	            display: flex;
78	            flex-direction: column;
79	            padding-top: env(safe-area-inset-top, 0px);
80	            padding-bottom: env(safe-area-inset-bottom, 0px);
81	        }
82	
83	        .header {
84	            padding: 16px 20px;
85	            border-bottom: 1px solid var(--border);
86	            background: var(--surface);
87	            display: flex;
88	            justify-content: space-between;
89	            align-items: center;
90	        }
91	
92	        .header h1 {
93	            margin: 0;
94	            font-size: 18px;
95	            font-weight: 600;
96	            color: var(--text-primary);
97	        }
98	
99	        .container {
100	            display: flex;
101	            flex: 1;
102	            overflow: hidden;
103	            gap: 0;
104	        }
105	
106	        .sidebar {
107	            width: 240px;
108	            border-right: 1px solid var(--border);
109	            background: var(--surface);
110	            display: flex;
111	            flex-direction: column;
112	            min-width: 0;
113	            overflow-y: auto;
114	        }
115	
116	        .sidebar-header {
117	            padding: 16px;
118	            font-weight: 600;
119	            font-size: 12px;
120	            text-transform: uppercase;
121	            color: var(--text-secondary);
122	            letter-spacing: 0.5px;
123	            border-bottom: 1px solid var(--border);
124	            display: flex;
125	            justify-content: space-between;
126	            align-items: center;
127	        }
128	
129	        .sidebar-header button {
130	            background: none;
131	            border: none;
132	            color: var(--accent);
133	            cursor: pointer;
134	            font-size: 16px;
135	            padding: 0;
136	            width: 24px;
137	            height: 24px;
138	            display: flex;
139	            align-items: center;
140	            justify-content: center;
141	        }
142	
143	        .sidebar-header button:hover {
144	            opacity: 0.8;
145	        }
146	
147	        .tables-list {
148	            flex: 1;
149	            overflow-y: auto;
150	            padding: 8px;
151	        }
152	
153	        .table-item {
154	            padding: 12px 12px;
155	            margin: 4px 0;
156	            border-radius: 6px;
157	            cursor: pointer;
158	            border: 1px solid transparent;
159	            transition: all 0.15s ease;
160	            color: var(--text-secondary);
161	            background: transparent;
162	            font-size: 13px;
163	            text-align: left;
164	            font-family: var(--font-system);
165	        }
166	
167	        .table-item:hover {
168	            background: var(--bg);
169	            color: var(--text-primary);
170	        }
171	
172	        .table-item.active {
173	            background: var(--accent);
174	            color: white;
175	            border-color: var(--accent);
176	        }
177	
178	        .main {
179	            flex: 1;
180	            display: flex;
181	            flex-direction: column;
182	            min-width: 0;
183	            overflow-y: auto;
184	        }
185	
186	        .main-header {
187	            padding: 20px;
188	            background: var(--surface);
189	            border-bottom: 1px solid var(--border);
190	            display: flex;
191	            justify-content: space-between;
192	            align-items: flex-start;
193	            gap: 20px;
194	        }
195	
196	        .main-header h2 {
197	            margin: 0;
198	            font-size: 16px;
199	            font-weight: 600;
200	            flex: 1;
201	        }
202	
203	        .main-header input {
204	            padding: 6px 10px;
205	            border: 1px solid var(--border);
206	            border-radius: 4px;
207	            font-size: 13px;
208	            background: var(--bg);
209	            color: var(--text-primary);
210	            font-family: var(--font-mono);
211	            flex: 0 1 200px;
212	        }
213	
214	        .main-content {
215	            flex: 1;
216	            padding: 20px;
217	            overflow-y: auto;
218	        }
219	
220	        .columns-list {
221	            display: flex;
222	            flex-direction: column;
223	            gap: 12px;
224	        }
225	
226	        .column-row {
227	            display: grid;
228	            grid-template-columns: 150px 140px 1fr auto;
229	            gap: 12px;
230	            align-items: center;
231	            padding: 12px;
232	            border: 1px solid var(--border);
233	            border-radius: 6px;
234	            background: var(--surface);
235	        }
236	
237	        .column-row input {
238	            padding: 8px 10px;
239	            border: 1px solid var(--border);
240	            border-radius: 4px;
241	            font-size: 13px;
242	            background: var(--bg);
243	            color: var(--text-primary);
244	        }
245	
246	        .column-row select {
247	            padding: 8px 10px;
248	            border: 1px solid var(--border);
249	            border-radius: 4px;
250	            font-size: 13px;
251	            background: var(--bg);
252	            color: var(--text-primary);
253	            cursor: pointer;
254	        }
255	
256	        .column-actions {
257	            display: flex;
258	            gap: 8px;
259	        }
260	
261	        .btn {
262	            padding: 6px 12px;
263	            border: 1px solid var(--border);
264	            border-radius: 4px;
265	            font-size: 12px;
266	            font-weight: 500;
267	            cursor: pointer;
268	            transition: all 0.15s ease;
269	            background: var(--bg);
270	            color: var(--text-primary);
271	            font-family: var(--font-system);
272	        }
273	
274	        .btn:hover {
275	            background: var(--surface);
276	            border-color: var(--text-secondary);
277	        }
278	
279	        .btn-primary {
280	            background: var(--accent);
281	            color: white;
282	            border-color: var(--accent);
283	        }
284	
285	        .btn-primary:hover {
286	            opacity: 0.9;
287	        }
288	
289	        .btn-danger {
290	            color: var(--error);
291	            border-color: var(--error);
292	        }
293	
294	        .btn-danger:hover {
295	            background: var(--error);
296	            color: white;
297	        }
298	
299	        .btn-small {
300	            padding: 4px 8px;
301	            font-size: 11px;
302	        }
303	
304	        .btn-icon {
305	            padding: 4px;
306	            width: 28px;
307	            height: 28px;
308	            display: flex;
309	            align-items: center;
310	            justify-content: center;
311	        }
312	
313	        .right-panel {
314	            width: 280px;
315	            border-left: 1px solid var(--border);
316	            background: var(--surface);
317	            display: flex;
318	            flex-direction: column;
319	            overflow-y: auto;
320	        }
321	
322	        .panel-section {
323	            padding: 16px;
324	            border-bottom: 1px solid var(--border);
325	        }
326	
327	        .panel-section h3 {
328	            margin: 0 0 12px 0;
329	            font-size: 12px;
330	            font-weight: 600;
331	            text-transform: uppercase;
332	            color: var(--text-secondary);
333	            letter-spacing: 0.5px;
334	        }
335	
336	        .field-type-button {
337	            display: block;
338	            width: 100%;
339	            padding: 10px 12px;
340	            margin-bottom: 8px;
341	            text-align: left;
342	            border: 1px solid var(--border);
343	            border-radius: 4px;
344	            background: var(--bg);
345	            color: var(--text-primary);
346	            cursor: pointer;
347	            font-size: 12px;
348	            font-weight: 500;
349	            transition: all 0.15s ease;
350	        }
351	
352	        .field-type-button:hover {
353	            border-color: var(--accent);
354	            background: var(--accent-light);
355	            color: var(--accent);
356	        }
357	
358	        .field-type-button small {
359	            display: block;
360	            font-size: 11px;
361	            color: var(--text-secondary);
362	            margin-top: 2px;
363	        }
364	
365	        .empty-state {
366	            display: flex;
367	            align-items: center;
368	            justify-content: center;
369	            height: 100%;
370	            text-align: center;
371	            color: var(--text-secondary);
372	        }
373	
374	        .empty-state p {
375	            margin: 0;
376	        }
377	
378	        .config-display {
379	            padding: 12px;
380	            background: var(--bg);
381	            border: 1px solid var(--border);
382	            border-radius: 4px;
383	            font-family: var(--font-mono);
384	            font-size: 11px;
385	            color: var(--text-secondary);
386	            overflow-x: auto;
387	            max-height: 200px;
388	            overflow-y: auto;
389	            white-space: pre-wrap;
390	            word-break: break-all;
391	        }
392	
393	        .metadata-input {
394	            width: 100%;
395	            padding: 6px 8px;
396	            border: 1px solid var(--border);
397	            border-radius: 4px;
398	            font-size: 12px;
399	            background: var(--bg);
400	            color: var(--text-primary);
401	        }
402	
403	        .metadata-label {
404	            font-size: 11px;
405	            color: var(--text-secondary);
406	            margin-bottom: 4px;
407	        }
408	
409	        .type-badge {
410	            display: inline-block;
411	            padding: 2px 6px;
412	            border-radius: 3px;
413	            font-size: 10px;
414	            font-weight: 500;
415	            text-transform: uppercase;
416	        }
417	
418	        .type-badge.relation {
419	            background: #fef3c7;
420	            color: #92400e;
421	        }
422	
423	        @media (prefers-color-scheme: dark) {
424	            .type-badge.relation {
425	                background: #451a03;
426	                color: #fbbf24;
427	            }
428	        }
429	
430	        @media (max-width: 1200px) {
431	            .right-panel {
432	                display: none;
433	            }
434	        }
435	
436	        @media (max-width: 768px) {
437	            .container {
438	                flex-direction: column;
439	            }
440	
441	            .sidebar {
442	                width: 100%;
443	                height: 120px;
444	                border-right: none;
445	                border-bottom: 1px solid var(--border);
446	                flex-direction: row;
447	                overflow-x: auto;
448	                overflow-y: hidden;
449	            }
450	
451	            .sidebar-header {
452	                display: none;
453	            }
454	
455	            .tables-list {
456	                display: flex;
457	                gap: 8px;
458	                padding: 8px;
459	                overflow-x: auto;
460	                flex-direction: row;
461	            }
462	
463	            .table-item {
464	                flex-shrink: 0;
465	                min-width: 120px;
466	            }
467	
468	            .column-row {
469	                grid-template-columns: 1fr;
470	                gap: 8px;
471	            }
472	
473	            .main-header {
474	                flex-direction: column;
475	            }
476	
477	            .main-header input {
478	                width: 100%;
479	                flex: 1;
480	            }
481	        }
482	    </style>
483	</head>
484	<body>
485	    <div class="header">
486	        <h1>Project Entry</h1>
487	        <div style="font-size: 12px; color: var(--text-secondary);">Table Template Designer</div>
488	    </div>
489	
490	    <div class="container">
491	        <!-- Sidebar: Tables List -->
492	        <div class="sidebar">
493	            <div class="sidebar-header">
494	                Tables
495	                <button onclick="addTable()" title="New table">+</button>
496	            </div>
497	            <div class="tables-list" id="tablesList"></div>
498	        </div>
499	
500	        <!-- Main: Column Editor -->
501	        <div class="main">
502	            <div class="main-header">
503	                <h2 id="currentTableName">Select a table</h2>
504	                <input type="text" id="tableNameInput" placeholder="Table name" style="display: none;">
505	                <div style="display: flex; gap: 8px;">
506	                    <button class="btn btn-icon" onclick="renameTable()" title="Rename table">✎</button>
507	                    <button class="btn btn-icon btn-danger" onclick="deleteCurrentTable()" title="Delete table">✕</button>
508	                </div>
509	            </div>
510	            <div class="main-content" id="mainContent">
511	                <div class="empty-state">
512	                    <p>Create or select a table to design columns</p>
513	                </div>
514	            </div>
515	        </div>
516	
517	        <!-- Right Panel: Field Type Picker -->
518	        <div class="right-panel">
519	            <div class="panel-section">
520	                <h3>Field Types</h3>
521	                <button class="field-type-button" onclick="addColumn('hex_id')">
522	                    hex_id
523	                    <small>4-char prefix + 12-char hex</small>
524	                </button>
525	                <button class="field-type-button" onclick="addColumn('text_single')">
526	                    text_single
527	                    <small>Single-line string</small>
528	                </button>
529	                <button class="field-type-button" onclick="addColumn('text_multi')">
530	                    text_multi
531	                    <small>Multi-line text block</small>
532	                </button>
533	                <button class="field-type-button" onclick="addColumn('int_scalar')">
534	                    int_scalar
535	                    <small>Integer with ghost-holder</small>
536	                </button>
537	                <button class="field-type-button" onclick="addColumn('float_scalar')">
538	                    float_scalar
539	                    <small>Float with ghost-holder</small>
540	                </button>
541	                <button class="field-type-button" onclick="addColumn('boolean')">
542	                    boolean
543	                    <small>Toggle 0 or 1</small>
544	                </button>
545	                <button class="field-type-button" onclick="addColumn('enum_single')">
546	                    enum_single
547	                    <small>Single select + inline create</small>
548	                </button>
549	                <button class="field-type-button" onclick="addColumn('enum_multi')">
550	                    enum_multi
551	                    <small>Multi-select tags</small>
552	                </button>
553	                <button class="field-type-button" onclick="addColumn('relation_single')">
554	                    relation_single
555	                    <small>Foreign key (1) — no create</small>
556	                </button>
557	                <button class="field-type-button" onclick="addColumn('relation_multi')">
558	                    relation_multi
559	                    <small>Foreign key array — no create</small>
560	                </button>
561	            </div>
562	
563	            <div class="panel-section">
564	                <h3>SQLite Schema</h3>
565	                <div class="config-display" id="sqliteDisplay">No table selected</div>
566	            </div>
567	
568	            <div class="panel-section">
569	                <h3>JSON Config</h3>
570	                <div class="config-display" id="configDisplay">No table selected</div>
571	            </div>
572	
573	            <div class="panel-section">
574	                <h3>Actions</h3>
575	                <button class="btn btn-primary" onclick="exportJson()" style="width: 100%; margin-bottom: 8px;">Export JSON</button>
576	                <button class="btn" onclick="exportSqlite()" style="width: 100%;">Export SQLite Schema</button>
577	            </div>
578	        </div>
579	    </div>
580	
581	    <script>
582	        // In-memory data structure
583	        let tables = {};
584	        let currentTable = null;
585	
586	        // Storage key for persistence
587	        const STORAGE_KEY = 'project_entry_tables';
588	
589	        // Initialize from localStorage
590	        function init() {
591	            try {
592	                const stored = localStorage.getItem(STORAGE_KEY);
593	                if (stored) {
594	                    tables = JSON.parse(stored);
595	                }
596	            } catch (e) {
597	                console.warn('Failed to load from localStorage:', e);
598	            }
599	
600	            renderTablesList();
601	
602	            if (Object.keys(tables).length === 0) {
603	                addTable();
604	            }
605	        }
606	
607	        function addTable() {
608	            const name = `table_${Date.now().toString(36)}`;
609	            tables[name] = {
610	                name: name,
611	                columns: []
612	            };
613	            currentTable = name;
614	            save();
615	            renderTablesList();
616	            selectTable(name);
617	        }
618	
619	        function deleteCurrentTable() {
620	            if (!currentTable) return;
621	            if (confirm(`Delete table "${currentTable}"?`)) {
622	                delete tables[currentTable];
623	                currentTable = Object.keys(tables)[0] || null;
624	                save();
625	                renderTablesList();
626	                if (currentTable) selectTable(currentTable);
627	                else renderMain();
628	            }
629	        }
630	
631	        function selectTable(name) {
632	            currentTable = name;
633	            renderTablesList();
634	            renderMain();
635	        }
636	
637	        function renameTable() {
638	            const input = document.getElementById('tableNameInput');
639	            const header = document.getElementById('currentTableName');
640	
641	            if (input.style.display === 'none') {
642	                input.style.display = 'block';
643	                input.value = currentTable;
644	                input.focus();
645	                header.style.display = 'none';
646	            } else {
647	                const newName = input.value.trim();
648	                if (newName && newName !== currentTable && !tables[newName]) {
649	                    tables[newName] = tables[currentTable];
650	                    tables[newName].name = newName;
651	                    delete tables[currentTable];
652	                    currentTable = newName;
653	                    save();
654	                    renderTablesList();
655	                    renderMain();
656	                }
657	                input.style.display = 'none';
658	                header.style.display = 'block';
659	            }
660	        }
661	
662	        function addColumn(fieldType) {
663	            if (!currentTable) return;
664	            const column = {
665	                id: `col_${Date.now()}`,
666	                name: `field_${tables[currentTable].columns.length + 1}`,
667	                type: fieldType,
668	                metadata: getDefaultMetadata(fieldType)
669	            };
670	            tables[currentTable].columns.push(column);
671	            save();
672	            renderMain();
673	        }
674	
675	        function getDefaultMetadata(type) {
676	            switch (type) {
677	                case 'enum_single':
678	                    return { options: ['option1', 'option2'] };
679	                case 'enum_multi':
680	                    return { options: ['tag1', 'tag2'] };
681	                case 'relation_single':
682	                case 'relation_multi':
683	                    return { target: 'self' };
684	                default:
685	                    return {};
686	            }
687	        }
688	
689	        function deleteColumn(colId) {
690	            if (!currentTable) return;
691	            tables[currentTable].columns = tables[currentTable].columns.filter(c => c.id !== colId);
692	            save();
693	            renderMain();
694	        }
695	
696	        function updateColumn(colId, field, value) {
697	            if (!currentTable) return;
698	            const col = tables[currentTable].columns.find(c => c.id === colId);
699	            if (col) {
700	                col[field] = value;
701	                save();
702	                updateConfigDisplays();
703	            }
704	        }
705	
706	        function updateColumnMetadata(colId, key, value) {
707	            if (!currentTable) return;
708	            const col = tables[currentTable].columns.find(c => c.id === colId);
709	            if (col) {
710	                col.metadata = col.metadata || {};
711	                if (key === 'options') {
712	                    col.metadata.options = value.split(',').map(o => o.trim()).filter(o => o);
713	                } else {
714	                    col.metadata[key] = value;
715	                }
716	                save();
717	                updateConfigDisplays();
718	            }
719	        }
720	
721	        function renderTablesList() {
722	            const list = document.getElementById('tablesList');
723	            list.innerHTML = '';
724	            Object.keys(tables).forEach(name => {
725	                const item = document.createElement('button');
726	                item.className = `table-item ${currentTable === name ? 'active' : ''}`;
727	                item.textContent = tables[name].name;
728	                item.onclick = () => selectTable(name);
729	                list.appendChild(item);
730	            });
731	        }
732	
733	        function renderMain() {
734	            const content = document.getElementById('mainContent');
735	
736	            if (!currentTable) {
737	                content.innerHTML = '<div class="empty-state"><p>Create a table to start</p></div>';
738	                document.getElementById('configDisplay').textContent = 'No table selected';
739	                document.getElementById('sqliteDisplay').textContent = 'No table selected';
740	                return;
741	            }
742	
743	            const table = tables[currentTable];
744	            document.getElementById('currentTableName').textContent = table.name;
