        fetch(DATA_PATH + 'sample_users.json').then(r => r.json()).catch(() => null),
        fetch(DATA_PATH + 'sample_projects.json').then(r => r.json()).catch(() => null),
      ]);
      files.forEach(f => {
        if (f && f.table_name) {
          tables[f.table_name] = f;
        }
      });
