/* Views Host */
.view-container {
  display: none;
  animation: fadeIn 0.15s ease;
}

.view-container.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Form & Workspace */
.workspace-grid {
  display: grid;
  grid-template-columns: 1fr 420px;
  gap: 1.5rem;
  align-items: start;
}

@media (max-width: 1024px) {
  .workspace-grid { grid-template-columns: 1fr; }
}

.blocks-stream {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.entry-card {
  background: var(--bg-card);
  border: 1px solid var(--border-dim);
  border-radius: var(--radius-md);
  overflow: visible !important;
  position: relative;
  box-shadow: var(--shadow-subtle);
}

.entry-card:focus-within {
  border-color: var(--border-mid);
  z-index: 50;
}

.card-header {
  padding: 0.85rem 1.15rem;
  background: rgba(255, 255, 255, 0.015);
  border-bottom: 1px solid var(--border-dim);
  display: flex;
  justify-content: space-between;
  align-items: center;
  user-select: none;
}

.card-title {
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--text-vivid);
}

.card-tag {
  font-family: "JetBrains Mono", monospace;
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--accent);
  background: var(--accent-bg);
  padding: 0.15rem 0.45rem;
  border-radius: 4px;
  border: 1px solid var(--accent-border);
  text-transform: uppercase;
}

.card-body {
  padding: 1.15rem;
  display: flex;
  flex-direction: column;
  gap: 1.1rem;
}

.field-label {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-muted);
  margin-bottom: 0.35rem;
}

.field-hint {
  font-size: 0.72rem;
  color: var(--text-dim);
  font-family: "JetBrains Mono", monospace;
}

/* Inputs */
.raw-input-box {
  width: 100%;
  height: 44px;
  background: var(--bg-input);
  border: 1px solid var(--border-dim);
  border-radius: var(--radius-sm);
  color: var(--text-vivid);
  font-family: inherit;
  font-size: 0.9rem;
  padding: 0 0.85rem;
  outline: none;
  transition: all 0.15s ease;
}

.raw-input-box:focus {
  background: var(--bg-input-focus);
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-glow);
}

.raw-textarea-box {
  width: 100%;
  min-height: 100px;
  background: var(--bg-input);
  border: 1px solid var(--border-dim);
  border-radius: var(--radius-sm);
  color: var(--text-vivid);
  font-family: "JetBrains Mono", monospace;
  font-size: 0.88rem;
  padding: 0.85rem;
  outline: none;
  resize: vertical;
  line-height: 1.6;
  transition: all 0.15s ease;
}

.raw-textarea-box:focus {
  background: var(--bg-input-focus);
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-glow);
}

/* Single Selector Styles */
.notion-combobox-wrap {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  overflow: visible !important;
}

.notion-combobox-trigger {
  width: 100%;
  min-height: 44px;
  background: var(--bg-input);
  border: 1px solid var(--border-mid);
  border-radius: var(--radius-sm);
  padding: 0.35rem 0.85rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  transition: all 0.15s ease;
  user-select: none;
}

.notion-combobox-trigger:hover,
.notion-combobox-trigger.active {
  background: var(--bg-input-focus);
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-glow);
}

.selected-val-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  background: var(--accent-bg);
  color: var(--accent);
  border: 1px solid var(--accent-border);
  padding: 0.2rem 0.6rem;
  border-radius: 4px;
  font-weight: 600;
  font-size: 0.85rem;
}

.combobox-chevron {
  color: var(--text-muted);
  font-size: 0.8rem;
  transition: transform 0.2s ease;
}

.notion-combobox-trigger.active .combobox-chevron {
  transform: rotate(180deg);
  color: var(--accent);
}

/* Suggestor Monolith */
.suggestor-host {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  overflow: visible !important;
}

.searcher-monolith {
  width: 100%;
  height: 44px;
  background: var(--bg-input);
  border: 1px solid var(--border-mid);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  padding: 0 0.85rem;
  gap: 0.65rem;
  transition: all 0.15s ease;
}

.searcher-monolith:focus-within {
  background: var(--bg-input-focus);
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-glow);
}

.searcher-icon {
  color: var(--accent);
  font-size: 1rem;
  flex-shrink: 0;
  user-select: none;
}

.searcher-input {
  width: 100%;
  height: 100%;
  background: transparent;
  border: none;
  outline: none;
  color: var(--text-vivid);
  font-size: 0.9rem;
  font-family: inherit;
}

.searcher-clear {
  background: rgba(255, 255, 255, 0.08);
  border: none;
  color: var(--text-muted);
  width: 22px;
  height: 22px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 0.75rem;
  flex-shrink: 0;
}

/* Selected Chips */
.selected-chips-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.selected-chips-row:empty { display: none; }

.chip-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  background: var(--accent-bg);
  color: var(--accent);
  border: 1px solid var(--accent-border);
  padding: 0.2rem 0.55rem;
  border-radius: 4px;
  font-size: 0.8rem;
  font-weight: 600;
  user-select: none;
}

.chip-remove {
  cursor: pointer;
  opacity: 0.7;
  font-size: 0.75rem;
  padding: 0 2px;
  border-radius: 2px;
}

.chip-remove:hover {
  opacity: 1;
  background: rgba(244, 63, 94, 0.2);
  color: #fb7185;
}

/* Dropdown Menus */
.notion-dropdown-menu {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;

