  right: 0;
  background: var(--bg-card);
  border: 1px solid var(--border-bright);
  border-radius: var(--radius-sm);
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.85);
  z-index: 1000 !important;
  display: none;
  flex-direction: column;
  overflow: hidden;
  max-height: 260px;
}

.notion-dropdown-menu.open { display: flex; }

.dropdown-options-list {
  overflow-y: auto;
  padding: 0.4rem;
  display: flex;
  flex-direction: column;
  gap: 2px;
  max-height: 200px;
}

.dropdown-opt-row {
  padding: 0.55rem 0.75rem;
  border-radius: 4px;
  font-size: 0.88rem;
  color: var(--text-main);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: background 0.1s ease;
  gap: 0.5rem;
}

.dropdown-opt-row:hover {
  background: var(--bg-input-focus);
  color: var(--accent);
}

.dropdown-opt-row.selected {
  background: var(--accent-bg);
  border: 1px solid var(--accent-border);
  color: var(--accent);
}

.opt-label-group {
  display: flex;
  flex-direction: column;
  min-width: 0;
  flex: 1 1 auto;
  gap: 2px;
}

.opt-title-row {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.opt-title {
  font-weight: 600;
  font-size: 0.88rem;
  color: var(--text-vivid);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.opt-context {
  font-size: 0.75rem;
  color: var(--text-muted);
  font-style: italic;
  opacity: 0.65;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.opt-delete-btn {
  background: transparent;
  border: 1px solid transparent;
  color: var(--text-dim);
  width: 22px;
  height: 22px;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  cursor: pointer;
  flex-shrink: 0;
}

.opt-delete-btn:hover {
  background: rgba(244, 63, 94, 0.18);
  border-color: rgba(244, 63, 94, 0.4);
  color: #fb7185;
}

.dropdown-create-row {
  padding: 0.6rem 0.75rem;
  background: var(--accent-bg);
  border-top: 1px solid var(--accent-border);
  color: var(--accent);
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.dropdown-create-row:hover {
  background: var(--accent);
  color: #080706;
}

/* CRUD Grid & Table Views */
.crud-view-wrap {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.crud-header-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem 1.25rem;
  background: var(--bg-card);
  border: 1px solid var(--border-dim);
  border-radius: var(--radius-md);
}

.crud-table {
  width: 100%;
  border-collapse: collapse;
  background: var(--bg-card);
  border: 1px solid var(--border-dim);
  border-radius: var(--radius-md);
  overflow: hidden;
}

.crud-table th {
  text-align: left;
  padding: 0.75rem 1rem;
  font-family: "JetBrains Mono", monospace;
  font-size: 0.72rem;
  color: var(--text-dim);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  background: rgba(255, 255, 255, 0.02);
  border-bottom: 1px solid var(--border-dim);
}

.crud-table td {
  padding: 0.85rem 1rem;
  font-size: 0.88rem;
  border-bottom: 1px solid var(--border-dim);
  color: var(--text-main);
  vertical-align: middle;
}

.crud-table tr:last-child td { border-bottom: none; }
.crud-table tr:hover td { background: var(--bg-card-hover); }

/* Tree View for Themes */
.theme-tree-node {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.65rem 0.85rem;
  background: var(--bg-card);
  border: 1px solid var(--border-dim);
  border-radius: var(--radius-sm);
  margin-bottom: 0.4rem;
  transition: all 0.15s ease;
}

.theme-tree-node:hover {
  border-color: var(--border-mid);
  background: var(--bg-card-hover);
}

.theme-tree-node.child-level-1 { margin-left: 1.5rem; border-left: 3px solid var(--accent); }
.theme-tree-node.child-level-2 { margin-left: 3rem; border-left: 3px solid var(--hazard-low); }

/* Visual Tree Cards (Read-Only Outliners) */
.tree-branch-group {
  background: var(--bg-card);
  border: 1px solid var(--border-dim);
  border-radius: var(--radius-sm);
  overflow: hidden;
  margin-bottom: 0.65rem;
}

.tree-branch-header {
  padding: 0.75rem 1rem;
  background: rgba(255, 255, 255, 0.02);
  border-bottom: 1px solid var(--border-dim);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.tree-branch-body {
  padding: 0.85rem 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.tree-subbranch {
  margin-left: 1.25rem;
  border-left: 2px solid var(--border-bright);
  padding-left: 0.85rem;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.tree-subbranch-2 {
  margin-left: 1.25rem;
  border-left: 2px solid var(--accent-border);
  padding-left: 0.85rem;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.badge-mock {
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.65rem;
  font-weight: 700;
  color: var(--accent);
  background: var(--accent-bg);
  border: 1px solid var(--accent-border);
  padding: 0.1rem 0.35rem;
  border-radius: 3px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* Inspector Sticky */
.inspector-sticky {
  position: sticky;
  top: 1.5rem;
  background: var(--bg-card);

      max-height: 90vh; /* Keeps entire box within viewport */
      display: flex;
      flex-direction: column; /* Flex layout so footer stays anchored */
      box-shadow: 0 20px 60px rgba(0, 0, 0, 0.85);
      overflow: hidden;
      animation: modalPop 0.15s cubic-bezier(0.16, 1, 0.3, 1);
    }

    @keyframes modalPop {
      from { transform: scale(0.96); opacity: 0; }
      to { transform: scale(1); opacity: 1; }
    }

    .modal-header {
      padding: 1rem 1.25rem;
      background: rgba(255, 255, 255, 0.02);
      border-bottom: 1px solid var(--border-dim);
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-shrink: 0;
    }

    .modal-body {
      padding: 1.25rem;
      display: flex;
      flex-direction: column;
      gap: 1rem;
      overflow-y: auto; /* SCROLLABLE! */
      flex: 1 1 auto;
      max-height: calc(90vh - 130px);
    }

    .modal-footer {
      padding: 0.85rem 1.25rem;
      background: rgba(255, 255, 255, 0.02);
      border-top: 1px solid var(--border-dim);
      display: flex;
      justify-content: flex-end;
      gap: 0.6rem;
      flex-shrink: 0; /* ANCHORED AT BOTTOM */
    }

    /* Toast */
    .toast-msg {
      position: fixed;
      bottom: 2rem;
      right: 2rem;
      background: var(--accent);
      color: #080706;
      font-weight: 700;
      font-size: 0.88rem;
      padding: 0.75rem 1.25rem;
      border-radius: var(--radius-sm);
      box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
      z-index: 6000;
      opacity: 0;
      transform: translateY(12px);
      transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
      pointer-events: none;
    }

    .toast-msg.show {
      opacity: 1;
      transform: translateY(0);
    }
  </style>
</head>
