  font-size: 0.76rem;
  color: var(--text-dim);
  background: var(--bg-input);
  border: 1px solid var(--border-dim);
  padding: 0.15rem 0.45rem;
  border-radius: 4px;
}

/* Filter Toolbar above stream */
.stream-toolbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.75rem;
  padding: 0.5rem 0;
}

.filter-pills-bar {
  display: flex;
  gap: 0.35rem;
  flex-wrap: wrap;
}

.filter-pill {
  background: var(--bg-card);
  border: 1px solid var(--border-dim);
  color: var(--text-muted);
  padding: 0.3rem 0.65rem;
  border-radius: var(--radius-sm);
  font-size: 0.76rem;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  transition: all 0.15s ease;
  font-family: inherit;
}
.filter-pill:hover {
  background: var(--bg-card-hover);
  color: var(--text-vivid);
}
.filter-pill.active {
  background: var(--accent-bg);
  border-color: var(--accent-border);
  color: var(--accent);
  font-weight: 700;
}

