const CAT_ICONS = {
  pk: '🔑',
  text: '📝',
  scalar: '🔢',
  boolean: '🔘',
  enum: '🏷️',
  rel: '🔗'
};

let activeCategoryFilter = 'all';
let collapsedCards = {};

function toSlug(str) {
  return (str || '')
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
}

function setCategoryFilter(cat) {
  activeCategoryFilter = cat;
  const pills = document.querySelectorAll('.filter-pill');
  pills.forEach(p => p.classList.remove('active'));
  const activeBtn = Array.from(pills).find(p => p.getAttribute('onclick')?.includes(`'${cat}'`));
  if (activeBtn) activeBtn.classList.add('active');
  renderActiveTable();
}

function toggleCardCollapse(idx, event) {
  if (event) event.stopPropagation();
  collapsedCards[idx] = !collapsedCards[idx];
  const card = document.getElementById(`col-card-${idx}`);
  if (card) {
    card.classList.toggle('collapsed', !!collapsedCards[idx]);
  }
}

function expandAllColumns() {
  collapsedCards = {};
  renderActiveTable();
}

function collapseAllColumns() {
  if (!activeTable || !tables[activeTable]) return;
  tables[activeTable].columns.forEach((_, i) => collapsedCards[i] = true);
  renderActiveTable();
}

// Render active table UI
function renderActiveTable() {
  if (!activeTable || !tables[activeTable]) return;
  const table = tables[activeTable];

  document.getElementById('input-table-name').value = table.table_name;
  document.getElementById('columns-summary-text').textContent =
    `${table.columns.length} Column${table.columns.length !== 1 ? 's' : ''} configured`;
  document.getElementById('sqlite-table-badge').textContent = `sqlite.${table.table_name}`;

  // Update category counts
  const counts = { all: table.columns.length, pk: 0, text: 0, scalar: 0, boolean: 0, enum: 0, rel: 0 };
  table.columns.forEach(c => {
    const cat = FIELD_SPECS[c.type]?.category;
    if (cat && counts[cat] !== undefined) counts[cat]++;
  });
  Object.keys(counts).forEach(k => {
    const el = document.getElementById(`count-${k}`);
    if (el) el.textContent = counts[k];
  });

  const streamEl = document.getElementById('columns-stream');
  const filteredCols = table.columns
    .map((col, idx) => ({ col, idx }))
    .filter(({ col }) => {
      if (activeCategoryFilter === 'all') return true;
      return FIELD_SPECS[col.type]?.category === activeCategoryFilter;
    });

  if (filteredCols.length === 0) {
    streamEl.innerHTML = `
      <div style="padding:2.5rem; text-align:center; color:var(--text-dim); background:var(--bg-card); border:1px dashed var(--border-mid); border-radius:var(--radius-md);">
        No columns match category filter "${activeCategoryFilter.toUpperCase()}". Click "All" or add a field below.
      </div>
    `;
    return;
  }

  streamEl.innerHTML = filteredCols.map(({ col, idx }) => renderColumnCard(col, idx)).join('');
}

// Column Card Renderer
function renderColumnCard(col, idx) {
  const spec = FIELD_SPECS[col.type] || FIELD_SPECS.text_single;
  const isCollapsed = !!collapsedCards[idx];
  const catIcon = CAT_ICONS[spec.category] || '🔹';
  const computerSlug = col.slug || toSlug(col.name) || `col_${idx + 1}`;

  return `
    <article class="entry-card cat-${spec.category} ${isCollapsed ? 'collapsed' : ''}" id="col-card-${idx}">
      <div class="card-header" onclick="toggleCardCollapse(${idx}, event)">
        <span class="card-title">
          <span class="collapse-chevron">▼</span>
          <span style="font-size:1.05rem;">${catIcon}</span>
          <span style="font-family:'JetBrains Mono', monospace; color:var(--text-dim); font-size:0.8rem;">#${idx + 1}</span>
          <span style="font-weight:700; color:var(--text-vivid); font-size:0.92rem;">${col.name || 'Untitled Field'}</span>
          <span class="slug-badge" title="SQLite Column Identifier">${computerSlug}</span>
        </span>
        <div style="display:flex; align-items:center; gap:0.45rem;" onclick="event.stopPropagation()">
          <span class="card-tag cat-${spec.category}">
            ${spec.slug}
          </span>
          <button class="btn-action" onclick="moveColumn(${idx}, -1)" title="Move Up" ${idx === 0 ? 'disabled style="opacity:0.3;"' : ''} style="padding:0.2rem 0.45rem; font-size:0.75rem;">
            ▲
          </button>
          <button class="btn-action" onclick="moveColumn(${idx}, 1)" title="Move Down" ${idx === tables[activeTable].columns.length - 1 ? 'disabled style="opacity:0.3;"' : ''} style="padding:0.2rem 0.45rem; font-size:0.75rem;">
            ▼
          </button>
          <button class="btn-action btn-danger" onclick="deleteColumn(${idx})" title="Delete Column" style="padding:0.2rem 0.45rem; font-size:0.75rem;">
            ✕
          </button>
        </div>
      </div>

      <div class="card-body">
        <!-- Row 1: Natural Language Name + Auto-Computed Slug -->
        <div class="field-grid-2">
          <div>
            <div class="field-label">
              <span>Natural Language Column Name</span>
              <span class="field-hint">Human label in JSON (name)</span>
            </div>
            <input type="text" class="raw-input-box" value="${col.name || ''}"
                   oninput="updateColName(${idx}, this.value)" placeholder="e.g. Account Username, Full Bio">
          </div>

          <div>
            <div class="field-label">
              <span>Computer Slug (SQLite Column Identifier)</span>
              <span class="field-hint">Auto-generated slug</span>
            </div>
            <input type="text" class="raw-input-box mono" value="${computerSlug}"
                   oninput="updateColSlug(${idx}, this.value)" placeholder="e.g. username, full_bio">
          </div>
        </div>

        <!-- Row 2: Type Selector + SQLite Readout -->
        <div class="field-grid-2">
          <div>
            <div class="field-label">
              <span>Atomic Data Entry Type</span>
              <span class="field-hint">1 of 10 specifications</span>
            </div>
            <select class="raw-input-box" onchange="updateColType(${idx}, this.value)">
              ${Object.keys(FIELD_SPECS).map(slug => `
                <option value="${slug}" ${col.type === slug ? 'selected' : ''}>
                  ${CAT_ICONS[FIELD_SPECS[slug].category]} #${FIELD_SPECS[slug].num} ${slug} — ${FIELD_SPECS[slug].title}
                </option>
              `).join('')}
            </select>
          </div>

          <div>
            <div class="field-label">
              <span>SQLite Column Specification</span>
              <span class="field-hint">Real Storage Engine</span>
            </div>
            <div class="raw-input-box mono" style="display:flex; align-items:center; color:var(--accent); background:var(--bg-canvas);">
              ${computerSlug} ${spec.sqlite}
            </div>
          </div>
        </div>

        <!-- Dynamic Metadata Configuration per Specification -->
        ${renderColumnMetadata(col, idx, spec)}

      </div>
    </article>
  `;
}

