              <span class="field-hint">Human label in JSON (name)</span>
            </div>
            <input type="text" class="raw-input-box" value="${col.name || ''}"
                   oninput="updateColName(${idx}, this.value)" placeholder="e.g. Account Username, Full Bio">
          </div>

