function updateColName(idx, newName) {
  if (!activeTable) return;
  const col = tables[activeTable].columns[idx];
  col.name = newName;
  if (!col.custom_slug) {
    col.slug = toSlug(newName) || `col_${idx + 1}`;
  }
  // Update header text in-place if not full re-render
  const headerTitle = document.querySelector(`#col-card-${idx} .card-title span:nth-child(4)`);
  if (headerTitle) headerTitle.textContent = newName || 'Untitled Field';
  const slugBadge = document.querySelector(`#col-card-${idx} .slug-badge`);
  if (slugBadge) slugBadge.textContent = col.slug;
  const slugInput = document.querySelector(`#col-card-${idx} input.raw-input-box.mono`);
  if (slugInput && !col.custom_slug) slugInput.value = col.slug;
  updateInspector();
}

function updateColSlug(idx, newSlug) {
  if (!activeTable) return;
  const col = tables[activeTable].columns[idx];
  col.slug = toSlug(newSlug) || `col_${idx + 1}`;
  col.custom_slug = true;
  const slugBadge = document.querySelector(`#col-card-${idx} .slug-badge`);
  if (slugBadge) slugBadge.textContent = col.slug;
  updateInspector();
}

function updateColProp(idx, prop, value) {
  if (!activeTable) return;
  tables[activeTable].columns[idx][prop] = value;
  updateInspector();
}

